// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. This is RWF-016's callee, unchanged -- what RWF-020 is about is
// the POSITION the call is written in, below.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// A heritage callee that RETURNS NORMALLY. RWF-020 asks only whether
// evaluating the heritage CALL completes; it makes, and must make, no
// claim about the returned value. An analyzer that fires on "a call in a
// heritage position" rather than on "a call this file proves can only
// throw" cuts the module off here and is wrong.
function baseFactory() {
  return class Base {};
}

// An `async` callee whose body throws. Calling it does NOT throw -- it
// returns a rejected promise -- so the CALL completes normally. The class
// definition below does ultimately fail, but with `TypeError: Class
// extends value #<Promise> is not a constructor or null`: an
// invalid-heritage-VALUE failure, a mechanism RWF-020 deliberately does
// not model. An analyzer reaching the right answer through this is right
// by accident.
async function asyncBail() {
  throw new Error("async bail rejects, it does not throw");
}

// A same-name decoy nested inside a function that is never called at
// module scope. Real JS lexical scoping never resolves the module-scope
// call below to this one, and the deferred body never runs at load time
// either -- so it changes no answer, and the oracle does not depend on it.
function configure() {
  function bail() {
    return class Configured {};
  }
  // A class carrying the exact RWF-020 shape, DEFERRED inside a function
  // body: `configure` is never called at module scope, so this class is
  // never evaluated during module evaluation and must poison nothing.
  class Deferred extends bail() {}
  return Deferred;
}

// Heritage clauses in the three shapes that genuinely do NOT end module
// evaluation, all evaluated at module scope. `baseFactory()` is called and
// returns; `null` is a legal superclass and evaluates no call at all.
// These are the controls that separate RWF-020's rule from a crude "any
// call in an extends clause" rule.
class Installed extends baseFactory() {}
class Rootless extends null {}

// A class with the throwing call in every position the language DEFERS:
// an instance field's VALUE (RWF-018's line) and a method BODY. Evaluating
// this definition installs an initializer and defines a method and
// executes neither.
class Probe extends baseFactory() {
  ready = bail();
  lazy() {
    return bail();
  }
}

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // The RWF-020 shape, and note what it is NOT: the class body is EMPTY.
  // There is no element of any kind -- no static field for RWF-018 to read
  // an initializer off, no computed key for RWF-019 to read a name off --
  // and no `static` token anywhere in the construct. The call is the
  // class's `extends` HERITAGE expression, which ClassDefinitionEvaluation
  // evaluates FIRST, before it does anything else with the class: the
  // superclass value has to exist before the prototype chain can be built.
  // So reaching this declaration necessarily invokes `bail`, which never
  // returns; `Mode` is never bound, and module evaluation on this branch
  // ends here.
  class Mode extends bail() {}
}

// Reached on every OTHER load, and on no load where the branch above was
// taken. Syntactically this is exactly what RWF-014 accepted: a bare
// identifier assigned by an unconditional top-level statement, last in the
// file, with no deferred write anywhere -- and RWF-015's return/throw
// cutoff, RWF-016's bare-call cutoff, RWF-017's variable-initializer
// cutoff, RWF-018's static-field cutoff and RWF-019's computed-key cutoff
// all find nothing here to object to either, since the file contains no
// module-scope `return`/`throw`, no bare `bail();` statement, no
// `const x = bail();` declaration, no `static` field at all and no
// computed key at all.
module.exports = slowPath;

// A last decoy, after the final write: the async callee in a heritage
// position, deferred inside a function nobody calls. It is here so that an
// analyzer tempted to reason from heritage RESULT types has something to
// be wrong about, and so that doing so changes no verdict.
function probeAsync() {
  class AsyncMode extends asyncBail() {}
  return AsyncMode;
}
void probeAsync;
void configure;
void Installed;
void Rootless;
void Probe;
